import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import { apiEditExperiment } from '../service/experiment'; // Import the API call

const PopUpContainer = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
`;

const PopUpForm = styled.div`
  background-color: white;
  padding: 20px;
  border-radius: 8px;
  width: 90%;
  max-height: 80%;
  overflow-y: auto;
  position: relative;
`;

const CloseButton = styled.button`
  position: absolute;
  top: 10px;
  right: 10px;
  background-color: transparent;
  border: none;
  font-size: 24px;
  cursor: pointer;
  color: #888;

  &:hover {
    color: #000;
  }
`;

const Title = styled.h3`
  text-align: center;
  font-size: 30px;
  margin-bottom: 20px;
`;

const InputField = styled.input`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border-radius: 5px;
  border: 1px solid #ccc;
`;

const Button = styled.button`
  padding: 10px 20px;
  font-size: 18px;
  background-color: #00aaff;
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.3s;

  &:hover {
    background-color: #0088cc;
  }
`;

const ExperimentEdit = ({ showModal, closeModal, experimentInfo }) => {
  const [name, setName] = useState('');
  const [code, setCode] = useState('');
  const [engineer, setEngineer] = useState('');
  const [createdTime, setCreatedTime] = useState('');

  // Initialize form fields with the experimentInfo data
  useEffect(() => {
    if (experimentInfo) {
      setName(experimentInfo.name);
      setCode(experimentInfo.code);
      setEngineer(experimentInfo.engineer);
      setCreatedTime(experimentInfo.createdTime);
    }
  }, [experimentInfo]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const updatedExperiment = await apiEditExperiment(experimentInfo._id, name, code, engineer, createdTime);
      console.log('Experiment updated successfully:', updatedExperiment);
      closeModal();  // Close the modal after successful submission
    } catch (error) {
      console.error('Error updating experiment:', error);
    }
  };

  if (!showModal) return null;

  return (
    <PopUpContainer>
      <PopUpForm>
        <CloseButton onClick={closeModal}>×</CloseButton>
        <Title>Chỉnh sửa thí nghiệm</Title>
        <form onSubmit={handleSubmit}>
          <div>
            <label>Tên thí nghiệm</label>
            <InputField
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
            />
          </div>
          <div>
            <label>Mã thí nghiệm</label>
            <InputField
              type="text"
              value={code}
              onChange={(e) => setCode(e.target.value)}
            />
          </div>
          <div>
            <label>Người thực hiện</label>
            <InputField
              type="text"
              value={engineer}
              onChange={(e) => setEngineer(e.target.value)}
            />
          </div>
          <div>
            <label>Thời gian tạo</label>
            <InputField
              type="text"
              value={createdTime}
              onChange={(e) => setCreatedTime(e.target.value)}
            />
          </div>
          <Button type="submit">Cập nhật thí nghiệm</Button>
        </form>
      </PopUpForm>
    </PopUpContainer>
  );
};

export default ExperimentEdit;
